/* ---------- Design review ---------- */
.drv{padding:16px;display:flex;flex-direction:column;gap:12px}
.drv-h{display:flex;align-items:center;gap:10px}
.drv-ic{width:32px;height:32px;border-radius:10px;background:var(--pb-bg);color:var(--pb);display:grid;place-items:center;flex:none;transition:background .4s,color .4s}
.drv.live .drv-ic{background:var(--ok-bg);color:var(--ok)}
.drv-ht{display:flex;flex-direction:column;min-width:0;flex:1}
.drv-ht b{font-weight:500;font-size:13.5px}
.drv-ht span{font-size:11.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.drv-b{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.15fr);gap:14px 18px;align-items:start}
@container (max-width:600px){.drv-b{grid-template-columns:minmax(0,1fr)}}
.drv-col{display:flex;flex-direction:column;gap:8px;min-width:0}
.drv-lb{font-size:11.5px;color:var(--muted);font-weight:500}
.drv-wt{font-size:12.5px;padding:3px 0}
.drv-checks{display:flex;flex-direction:column;border-radius:12px;background:var(--chip);padding:4px}
.drv-c{display:flex;align-items:center;gap:10px;padding:7px 8px;font-size:12.5px}
.drv-c .g{width:16px;height:16px;display:grid;place-items:center;flex:none}
.drv-c .t{flex:1;min-width:0}
.drv-c .d{color:var(--muted);font-size:12px;text-align:right}
.drv-ring{width:12px;height:12px;border-radius:50%;box-shadow:inset 0 0 0 1.5px var(--faint)}
.drv-rv{display:flex;flex-direction:column;gap:10px;min-height:150px}
@container (max-width:600px){.drv-rv{min-height:0}}
.drv-m{display:flex;align-items:flex-start;gap:9px;font-size:12.5px}
.drv-m .av{width:22px;height:22px;margin-top:1px}
.drv-ag{width:22px;height:22px;border-radius:50%;background:var(--chip);color:var(--fg2);display:grid;place-items:center;flex:none;margin-top:1px}
.drv-mb{display:flex;flex-direction:column;gap:3px;min-width:0;flex:1}
.drv-mn{display:flex;align-items:center;gap:7px;min-height:22px;flex-wrap:wrap}
.drv-mn b{font-weight:500}
.drv-mb p{margin:0;color:var(--fg2);line-height:1.45}
.drv-f{display:flex;align-items:center;gap:10px;position:relative;padding-top:2px}
.drv-st{flex:1;min-width:0;font-size:12.5px}
.drv-mg{display:flex;gap:1px;flex:none}
.drv-go{border-radius:999px 0 0 999px;padding-right:12px}
.drv-dd{border-radius:0 999px 999px 0;padding:0 9px}
.drv-pop{min-width:230px}
.drv-done{display:flex;align-items:center;gap:8px;font-size:13px;flex:1}
.drv-done svg{color:var(--ok)}
.drv-wk .spin{width:9px;height:9px;border-width:1.3px}

DM.def('design-review', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{palette}', I('palette')).replace('{chev}', I('chev-d','xs')).replace(/\{chk\}/g, I('check','xs'));
  const C = [['Visual diff','2 of 6 screens changed'],['Library tokens','All from the library'],['Contrast','AA on every screen']];
  const box = $('.drv-checks', r), rv = $('.drv-rv', r), go = $('.drv-go', r), dd = $('.drv-dd', r), st = $('.drv-st', r), tag = $('.drv-tag', r), root = $('.drv', r);
  box.innerHTML = C.map(x => `<div class="drv-c"><span class="g"><span class="drv-ring"></span></span><span class="t">${x[0]}</span><span class="d"></span></div>`).join('');
  const rows = $$('.drv-c', box);
  const DONE = { 'Ship to everyone':'Live for every visitor', 'Ship to 10% first':'Live for 10% of visitors. Everyone tomorrow', 'Ship on Monday':'Ships on Monday at 09:00' };
  // one message in the review: who, a tag, and what they said
  const msg = (who, tg, text) => { const m = html(`<div class="drv-m">${who === 'agent' ? `<span class="drv-ag">${I('spark','xs')}</span>` : AV('MK','var(--pl)')}<div class="drv-mb"><span class="drv-mn"><b>${who === 'agent' ? 'Design agent' : 'Maya Kim'}</b>${tg}</span>${text ? `<p>${text}</p>` : ''}</div></div>`); $('.drv-wt', rv)?.remove(); rv.appendChild(m); enter(m); return m; };
  $$('.drv-pop .mi', r).forEach(m => m.addEventListener('click', () => { $$('.drv-pop .mi', r).forEach(x => x.setAttribute('aria-checked', x === m)); swap(go, m.dataset.m); }));
  go.onclick = () => c.run(async () => {
    const how = go.textContent; go.disabled = dd.disabled = true; swap(go, 'Shipping'); swap(st, 'Publishing 6 screens'); await c.wait(1000);
    const later = how === 'Ship on Monday';
    root.classList.toggle('live', !later); tag.className = 'tag ' + (later ? 'b' : 'ok') + ' drv-tag'; swap(tag, later ? 'Scheduled' : 'Live');
    const f = $('.drv-f', r); f.innerHTML = `<span class="drv-done">${I(later ? 'clock' : 'ok')}<span>${DONE[how]}</span></span>`; enter(f.firstElementChild);
  });
  c.run(async () => {
    await c.wait(500);
    for (let i = 0; i < rows.length; i++){
      const g = $('.g', rows[i]); g.innerHTML = '<span class="spin"></span>'; swap($('.d', rows[i]), 'Running');
      await c.wait(650 + i * 120);
      g.innerHTML = `<span style="color:var(--ok);display:grid">${I('ok','xs')}</span>`; enter(g.firstElementChild); swap($('.d', rows[i]), C[i][1]);
    }
    swap(st, 'Waiting on Maya'); await c.wait(900);
    msg('maya', '<span class="tag warn">Changes requested</span>', 'Start the plan toggle on yearly. Most people pick it.');
    swap(st, 'The agent is on it'); await c.wait(1200);
    const a = msg('agent', '<span class="tag drv-wk"><span class="spin"></span>Updating</span>', '');
    await c.wait(1300);
    swap($('.drv-wk', a), 'Updated'); const p = html('<p>The toggle starts on yearly on all 6 screens.</p>'); $('.drv-mb', a).appendChild(p); enter(p);
    await c.wait(1100);
    msg('maya', `<span class="tag ok">${I('check','xs')}Approved</span>`, '');
    swap(st, 'Approved by Maya'); tag.className = 'tag ok drv-tag'; swap(tag, 'Approved');
    go.disabled = dd.disabled = false; enter($('.drv-mg', r));
  });
});
